import { apiInitializer } from "discourse/lib/api";

export default apiInitializer("0.8", (api) => {
  const debug = new URLSearchParams(window.location.search).get("mrf_debug") === "1";
  const log = (...args) => {
    if (debug && window.console && console.log) console.log("[MRF GTM]", ...args);
  };

  window.dataLayer = window.dataLayer || [];
  window.__mrf_seen_posts = window.__mrf_seen_posts || new Set();

  function getVirtualPageView() {
    try {
      const dl = window.dataLayer || [];
      // find last virtualPageView
      for (let i = dl.length - 1; i >= 0; i--) {
        const x = dl[i];
        if (x && x.event === "virtualPageView" && x.page) return x;
      }
    } catch (e) {}
    return null;
  }

  function getTopicTitle() {
    const v = getVirtualPageView();
    return (v && v.page && v.page.title) ? String(v.page.title) : (document.title || "");
  }

  function getTopicUrl() {
    const v = getVirtualPageView();
    return (v && v.page && v.page.url) ? String(v.page.url) : (location.pathname + location.search + location.hash);
  }

  function findPostNodes() {
    // broad selector to survive theme variations
    let nodes = Array.from(document.querySelectorAll("article[data-post-id][data-user-id]"));
    if (!nodes.length) nodes = Array.from(document.querySelectorAll("[data-post-id][data-user-id]"));
    return nodes;
  }

  function getPostNumber(el) {
    // Some themes store it as data-post-number; otherwise try common DOM hooks.
    let pn =
      el.getAttribute?.("data-post-number") ||
      el.dataset?.postNumber ||
      el.querySelector?.(".post-number")?.textContent ||
      el.querySelector?.("a.post-number")?.textContent ||
      null;

    if (pn) return String(pn).trim();

    // As a last resort: parse trailing /<postNumber> from /t/slug/id/<postNumber>
    const m = (location.pathname || "").match(/\/t\/[^/]+\/\d+\/(\d+)(?:\/)?$/);
    return m && m[1] ? m[1] : null;
  }

  function postMeta(el) {
    const postId = el.getAttribute?.("data-post-id") || el.dataset?.postId || null;
    const authorId = el.getAttribute?.("data-user-id") || el.dataset?.userId || null;
    if (!postId || !authorId) return null;

    return {
      postId: String(postId),
      authorId: String(authorId),
      postNumber: getPostNumber(el)
    };
  }

  function push(meta) {
    if (!meta) return;
    if (window.__mrf_seen_posts.has(meta.postId)) return;
    window.__mrf_seen_posts.add(meta.postId);

    const payload = {
      event: "mrf_post_in_view",
      mrf_topic_title: getTopicTitle(),
      mrf_topic_url: getTopicUrl(),
      mrf_post_id: meta.postId,
      mrf_post_number: meta.postNumber,
      mrf_author_user_id: meta.authorId
    };

    window.dataLayer.push(payload);
    log("dataLayer.push", payload);
  }

  function setupObservers() {
    const posts = findPostNodes();
    log("Found post nodes:", posts.length);

    // marker so you can confirm script is alive even if posts not found
    window.dataLayer.push({ event: "mrf_theme_loaded", mrf_path: location.pathname });
    log("mrf_theme_loaded pushed");

    if (!posts.length) return;

    const io = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        push(postMeta(entry.target));
      }
    }, { threshold: 0.6 });

    posts.forEach(p => io.observe(p));

    // Watch for infinite scroll / post inserts
    const mo = new MutationObserver((mutations) => {
      for (const m of mutations) {
        for (const n of m.addedNodes || []) {
          if (!(n instanceof HTMLElement)) continue;

          if (n.matches?.("article[data-post-id][data-user-id], [data-post-id][data-user-id]")) {
            io.observe(n);
            continue;
          }

          const found = n.querySelectorAll?.("article[data-post-id][data-user-id], [data-post-id][data-user-id]") || [];
          found.forEach(f => io.observe(f));
        }
      }
    });

    mo.observe(document.body, { childList: true, subtree: true });

    // Immediately push first few posts (helps when already in view)
    posts.slice(0, 5).forEach(p => push(postMeta(p)));
  }

  api.onPageChange(() => {
    // Run now and again after Ember paints
    setupObservers();
    setTimeout(setupObservers, 800);
  });
});

import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { on } from "@ember/modifier";
import { switchTheme } from "../lib/mrf-theme-switch";

export default class MrfFooter extends Component {
  @service currentUser;

  get year() {
    return new Date().getFullYear();
  }

  get showClassicLink() {
    return parseInt(settings.classic_theme_id, 10) > 0;
  }

  @action
  backToClassic(event) {
    event.preventDefault();
    switchTheme(this.currentUser, settings.classic_theme_id, "footer");
  }

  <template>
    <footer class="mrf-footer">
      <div class="mrf-footer__inner">
        <div class="mrf-footer__brand">
          <a class="mrf-footer__logo" href="/">
            <span class="mrf-strata" aria-hidden="true">
              <span class="mrf-strata__bar"></span>
              <span class="mrf-strata__bar"></span>
              <span class="mrf-strata__bar"></span>
              <span class="mrf-strata__bar"></span>
            </span>
            <span class="mrf-footer__logo-text">
              <span class="mrf-footer__logo-name">Mineral Rights Forum</span>
              <span class="mrf-footer__logo-sub">Est. 2009</span>
            </span>
          </a>
          {{#if settings.footer_tagline}}
            <p class="mrf-footer__tagline">{{settings.footer_tagline}}</p>
          {{/if}}
        </div>

        {{#each settings.footer_sections as |section|}}
          <div class="mrf-footer__col">
            <h4>{{section.heading}}</h4>
            {{#each section.links as |link|}}
              <a href={{link.url}}>{{link.text}}</a>
            {{/each}}
          </div>
        {{/each}}
      </div>

      <div class="mrf-footer__bottom">
        <span>© {{this.year}} Mineral Rights Forum. All rights reserved.</span>
        {{#if this.showClassicLink}}
          <a
            href
            class="mrf-footer__classic"
            {{on "click" this.backToClassic}}
          >{{settings.classic_link_label}}</a>
        {{/if}}
      </div>
    </footer>
  </template>
}

import Component from "@glimmer/component";
import { service } from "@ember/service";
import { defaultHomepage } from "discourse/lib/utilities";

export default class MrfHero extends Component {
  @service router;

  get shouldShow() {
    if (!settings.show_hero) {
      return false;
    }

    const path = (this.router.currentURL || "/").split(/[?#]/)[0];
    return path === "/" || path === `/${defaultHomepage()}`;
  }

  <template>
    {{#if this.shouldShow}}
      <section class="mrf-hero">
        <div class="mrf-hero__inner">
          {{#if settings.hero_eyebrow}}
            <span class="mrf-hero__eyebrow">{{settings.hero_eyebrow}}</span>
          {{/if}}

          <h1 class="mrf-hero__title">{{settings.hero_title}}</h1>

          {{#if settings.hero_subtitle}}
            <p class="mrf-hero__lead">{{settings.hero_subtitle}}</p>
          {{/if}}

          {{#if settings.hero_stats.length}}
            <div class="mrf-hero__stats">
              {{#each settings.hero_stats as |stat|}}
                <div class="mrf-hero__stat">
                  <span class="mrf-hero__stat-n">{{stat.value}}</span>
                  <span class="mrf-hero__stat-l">{{stat.label}}</span>
                </div>
              {{/each}}
            </div>
          {{/if}}

          <div class="mrf-hero__actions">
            {{#if settings.hero_primary_label}}
              <a
                class="mrf-btn mrf-btn--gold"
                href={{settings.hero_primary_url}}
              >{{settings.hero_primary_label}}</a>
            {{/if}}
            {{#if settings.hero_secondary_label}}
              <a
                class="mrf-btn mrf-btn--ghost"
                href={{settings.hero_secondary_url}}
              >{{settings.hero_secondary_label}}</a>
            {{/if}}
          </div>
        </div>
      </section>
    {{/if}}
  </template>
}

import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";

const COOKIE_NAME = "theme_ids";
const TEN_YEARS = 60 * 60 * 24 * 365 * 10;

function setDeviceTheme(themeId, seq) {
  const secure = window.location.protocol === "https:" ? "; secure" : "";

  if (themeId) {
    document.cookie = `${COOKIE_NAME}=${themeId}|${seq}; path=/; max-age=${TEN_YEARS}; samesite=lax${secure}`;
  } else {
    document.cookie = `${COOKIE_NAME}=; path=/; max-age=0; samesite=lax${secure}`;
  }
}

export async function switchTheme(currentUser, themeId, source) {
  themeId = parseInt(themeId, 10);
  if (!themeId) {
    return;
  }

  try {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
      event: "mrf_theme_switch",
      mrf_theme_id: themeId,
      mrf_switch_source: source || null,
      mrf_logged_in: !!currentUser,
    });
  } catch (e) {}

  try {
    if (currentUser) {
      await ajax(`/u/${currentUser.username_lower}.json`, {
        type: "PUT",
        data: { theme_ids: [themeId] },
      });
      setDeviceTheme(null);
    } else {
      setDeviceTheme(themeId, 0);
    }
    window.location.reload();
  } catch (e) {
    popupAjaxError(e);
  }
}

$navy: #0a192f;
$navy-mid: #0e2040;
$navy-light: #1a3054;
$gold: #d4a520;
$gold-hover: #e0b535;
$gold-dim: rgba(212, 165, 32, 0.12);
$gold-border: rgba(212, 165, 32, 0.28);
$off-white: #f8f6f1;
$card-radius: 12px;
$serif: "Playfair Display", Georgia, serif;
$sans: Inter, ui-sans-serif, system-ui, -apple-system, sans-serif;

:root {
  --font-family: #{$sans};
  --heading-font-family: #{$serif};
  --mrf-navy: #{$navy};
  --mrf-gold: #{$gold};
  --mrf-gold-hover: #{$gold-hover};
  --d-link-color: var(--primary);
  --d-button-border-radius: 7px;
  --d-button-primary-bg-color: #{$gold};
  --d-button-primary-text-color: #{$navy};
  --d-button-primary-icon-color: #{$navy};
  --d-button-primary-bg-color--hover: #{$gold-hover};
  --d-button-primary-text-color--hover: #{$navy};
  --d-button-primary-icon-color--hover: #{$navy};
}

html body {
  font-family: var(--font-family);
}

h1,
h2,
h3,
.fancy-title,
#topic-title h1,
.category-title-header .category-title-name,
.category-heading h1 {
