import { schedule } from "@ember/runloop";
import { apiInitializer } from "discourse/lib/api";
import MrfFooter from "../components/mrf-footer";
import MrfHero from "../components/mrf-hero";
import MrfNav from "../components/mrf-nav";

const MrfNavHeader = <template><MrfNav @variant="header" /></template>;
const MrfNavBar = <template><MrfNav @variant="bar" /></template>;

function placeBannerBelowHero() {
  const banner = document.querySelector(".alert-banner");
  const hero = document.querySelector(".mrf-hero");
  if (!banner || !hero) {
    return;
  }

  const bannerWrap = banner.closest(".below-site-header-outlet") || banner;
  const heroWrap = hero.closest(".below-site-header-outlet") || hero;
  if (
    bannerWrap === heroWrap ||
    bannerWrap.parentNode !== heroWrap.parentNode ||
    heroWrap.nextElementSibling === bannerWrap
  ) {
    return;
  }

  heroWrap.after(bannerWrap);
}

export default apiInitializer((api) => {
  api.renderInOutlet("before-header-panel", MrfNavHeader);
  api.renderInOutlet("below-site-header", MrfNavBar);
  api.renderInOutlet("below-site-header", MrfHero);
  api.renderInOutlet("below-footer", MrfFooter);

  api.onPageChange(() => {
    schedule("afterRender", placeBannerBelowHero);
    setTimeout(placeBannerBelowHero, 300);
  });
});

import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { service } from "@ember/service";

export default class MrfNav extends Component {
  @service router;

  @tracked openIndex = null;
  @tracked mobileOpen = false;

  constructor() {
    super(...arguments);
    this.router.on("routeDidChange", this, this.closeAll);
    document.addEventListener("click", this.onDocumentClick);
    document.addEventListener("keydown", this.onKeydown);
  }

  willDestroy() {
    super.willDestroy(...arguments);
    this.router.off("routeDidChange", this, this.closeAll);
    document.removeEventListener("click", this.onDocumentClick);
    document.removeEventListener("keydown", this.onKeydown);
  }

  get isBar() {
    return this.args.variant === "bar";
  }

  get items() {
    return (settings.nav_menu || []).map((item, index) => {
      const links = item.links || [];
      return {
        index,
        label: item.label,
        url: item.url,
        links,
        hasLinks: links.length > 0,
        isOpen: this.openIndex === index,
      };
    });
  }

  @action
  closeAll() {
    this.openIndex = null;
    this.mobileOpen = false;
  }

  @action
  onDocumentClick(event) {
    if (this.openIndex === null && !this.mobileOpen) {
      return;
    }
    if (!event.target?.isConnected) {
      return;
    }
    if (!event.target.closest?.(`.mrf-nav--${this.args.variant}`)) {
      this.closeAll();
    }
  }

  @action
  onKeydown(event) {
    if (event.key === "Escape") {
      this.closeAll();
    }
  }

  @action
  toggleItem(index, event) {
    event.preventDefault();
    this.openIndex = this.openIndex === index ? null : index;
  }

  @action
  toggleMobile() {
    this.mobileOpen = !this.mobileOpen;
    if (!this.mobileOpen) {
      this.openIndex = null;
    }
  }

  @action
  onMouseLeave() {
    if (!this.isBar) {
      this.openIndex = null;
    }
  }

  <template>
    <nav
      class="mrf-nav mrf-nav--{{@variant}} {{if this.mobileOpen 'is-mobile-open'}}"
      aria-label="Main menu"
      {{on "mouseleave" this.onMouseLeave}}
    >
      {{#if this.isBar}}
        <button
          type="button"
          class="mrf-nav__toggle"
          aria-expanded={{if this.mobileOpen "true" "false"}}
          {{on "click" this.toggleMobile}}
        >
          <span class="mrf-nav__toggle-icon" aria-hidden="true">
            <span></span><span></span><span></span>
          </span>
          {{settings.nav_mobile_label}}
        </button>
      {{/if}}

      <ul class="mrf-nav__list">
        {{#each this.items key="index" as |item|}}
          <li
            class="mrf-nav__item
              {{if item.hasLinks 'has-dropdown'}}
              {{if item.isOpen 'is-open'}}"
          >
            {{#if item.hasLinks}}
              <button
                type="button"
                class="mrf-nav__top"
                aria-haspopup="true"
                aria-expanded={{if item.isOpen "true" "false"}}
                {{on "click" (fn this.toggleItem item.index)}}
              >
                {{item.label}}
                <svg
                  class="mrf-nav__chevron"
                  viewBox="0 0 10 10"
                  aria-hidden="true"
                ><path
                    d="M1.5 3.5 5 7l3.5-3.5"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="1.6"
                    stroke-linecap="round"
                    stroke-linejoin="round"
                  /></svg>
              </button>
              <ul class="mrf-nav__dropdown">
                {{#each item.links as |link|}}
                  <li>
                    <a
                      class="mrf-nav__link"
                      href={{link.url}}
                      target={{if link.new_tab "_blank"}}
                      rel={{if link.new_tab "noopener"}}
                      {{on "click" this.closeAll}}
                    >{{link.text}}</a>
                  </li>
                {{/each}}
              </ul>
            {{else}}
              <a
                class="mrf-nav__top"
                href={{item.url}}
                {{on "click" this.closeAll}}
              >{{item.label}}</a>
            {{/if}}
          </li>
        {{/each}}
      </ul>
    </nav>
  </template>
}

